export function BridgeManager({ call }: { call: Caller }) {
  const [tab, setTab] = useState(0), [stats, setStats] = useState<any>(null), [error, setError] = useState(''), [notice, setNotice] = useState('');
  const [items, setItems] = useState<Memory[]>([]), [imports, setImports] = useState<any[]>([]), [history, setHistory] = useState<any[]>([]), [conflicts, setConflicts] = useState<any[]>([]), [backups, setBackups] = useState<any[]>([]), [actions, setActions] = useState<any[]>([]);
  const [query, setQuery] = useState(''), [status, setStatus] = useState('candidate'), [category, setCategory] = useState(''), [offset, setOffset] = useState(0), [busy, setBusy] = useState(false), [upload, setUpload] = useState('');
  const [selected, setSelected] = useState<Memory | null>(null), [conversation, setConversation] = useState<any>(null), [revisions, setRevisions] = useState<any[]>([]), [checked, setChecked] = useState<string[]>([]);
  const [confirmation, setConfirmation] = useState<any>(null), [acknowledged, setAcknowledged] = useState(false), [mergeText, setMergeText] = useState('');
  const [autoRecall, setAutoRecall] = useState(false), [budget, setBudget] = useState(800), [limit, setLimit] = useState(6), [keep, setKeep] = useState(10);
  const [endpoint, setEndpoint] = useState('http://127.0.0.1:11434/v1/'), [model, setModel] = useState(''), [keyEnv, setKeyEnv] = useState(''), [remoteConsent, setRemoteConsent] = useState(false);

  const [storagePath, setStoragePath] = useState('D:\\DeepSeekMemoryBridge'), [folderBrowser, setFolderBrowser] = useState<any>(null);

  const refresh = useCallback(async () => {
    const [s, a] = await Promise.all([call('stats'), call('actions')]); setStats(s); setActions(a);
    if (tab === 0) setImports(await call('imports'));
    if (tab === 1) setItems(query ? await call('search', { query, limit: 50 }) : await call('memories', { status, category, offset, limit: 50 }));
    if (tab === 2) setHistory(await call('history', { query, offset, limit: 50 }));
    if (tab === 3) setConflicts(await call('conflicts'));
    if (tab === 4) setBackups(await call('backups'));
  }, [call, tab, query, status, category, offset]);
  useEffect(() => { void refresh().catch(e => setError(e.message)); }, [refresh]);
  useEffect(() => { const timer = setInterval(() => { void call('stats').then(setStats).catch(() => {}); }, 2000); return () => clearInterval(timer); }, [call]);
  useEffect(() => { if (!stats) return; setAutoRecall(stats.settings.autoRecall); setBudget(stats.settings.recallBudgetTokens); setLimit(stats.settings.recallLimit); setKeep(stats.settings.backupKeep); }, [stats?.settings?.autoRecall, stats?.settings?.recallBudgetTokens, stats?.settings?.recallLimit, stats?.settings?.backupKeep]);
  const run = async (fn: () => Promise<void>) => { setBusy(true); setError(''); try { await fn(); } catch (e) { setError(e instanceof Error ? e.message : '操作失败'); } finally { setBusy(false); } };
  const propose = async (type: string, payload: Record<string, unknown>, description: string) => {
    const p = await call('propose', { type, payload, description }); const all = await call('actions'); setActions(all);
    setConfirmation(all.find((a: any) => a.id === p.actionId)); setAcknowledged(false);
  };
  const openConversation = (id: string, version?: string, page = 0) => run(async () => { setConversation(await call('conversation', { id, version, offset: page, limit: 50 })); });
  const uploadFile = async (file: File) => run(async () => {
    const start = await call('upload-start', { name: file.name, bytes: file.size });
    for (let n = 0; n < file.size; n += 65536) {
      const chunk = new Uint8Array(await file.slice(n, n + 65536).arrayBuffer()); let binary = ''; for (const b of chunk) binary += String.fromCharCode(b);
      await call('upload-chunk', { id: start.id, offset: n, data: btoa(binary) }); setUpload(`上传 ${Math.min(n + chunk.length, file.size)} / ${file.size} 字节`);
    }
    setUpload('正在本地解析和检查重复'); const preview = await call('upload-finish', { id: start.id }); setUpload(''); setNotice(`预览完成：${preview.parseable} 个可解析会话。核对下方统计后确认导入。`); await refresh();
  });
  const review = (m: Memory, value: string) => run(() => propose('review', { id: m.id, status: value, revision: m.revision }, `将记忆设为${statuses[value]}：${m.content}`));
  const downloadRaw = () => run(async () => { const raw = await call('raw-conversation', { id: conversation.id, version: conversation.version }); const blob = new Blob([JSON.stringify(raw, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = 'conversation.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); });
  const switchTab = (i: number) => { setTab(i); setQuery(''); setOffset(0); setSelected(null); setConversation(null); setChecked([]); };
  const browse = async (path?: string) => { setFolderBrowser(await call('storage-browse', { path })); };
  const chooseFolder = () => run(async () => {
    const picked = await call('storage-pick');
    if (picked.path) setStoragePath(picked.path); else await browse();
  });
  return <div className="dmb"><style>{css}</style>
    <div className="brand"><svg className="mark" viewBox="0 0 36 30" aria-hidden="true"><path d="M2 24V9h9v15M25 24V9h9v15M10 13c5-10 11-10 16 0M7 24h22" fill="none" stroke="currentColor" strokeWidth="2"/></svg><div><strong>DeepSeek Memory Bridge</strong><br/><small>本地历史与长期记忆 · 0.2.2</small></div></div>
    <div className="sheet"><div className="titlebar"><div><h1>{tabs[tab]}</h1><p className="muted">原文留存、证据审核、按需召回。数据保存在这台电脑。</p></div><div className="stack"><a className="manual-link" href="https://github.com/baimengyan242-dot/BAI/blob/main/deepseek-memory-bridge/docs/USER_GUIDE.zh-CN.md" target="_blank" rel="noreferrer">使用说明</a><button onClick={() => void run(refresh)} disabled={busy}>刷新</button></div></div>
      <nav className="nav" aria-label="记忆管理导航" role="tablist">{tabs.map((t, i) => <button role="tab" aria-selected={tab === i} key={t} onClick={() => switchTab(i)}>{t}{i === 3 && stats?.conflicts ? ` (${stats.conflicts})` : ''}</button>)}</nav>
      {error && !confirmation && <div className="notice error" role="alert">{error}<button className="link" onClick={() => setError('')}>关闭</button></div>}
      {notice && <div className="notice" role="status">{notice}<button className="link" onClick={() => setNotice('')}>收起</button></div>}
      {!stats ? <div className="empty">正在读取本地记忆库…</div> : <div className="numbers">{[[stats.conversations, '原始会话'], [stats.messages, '当前版本消息'], [stats.candidates, '待审核记忆'], [stats.confirmed, '已确认记忆']].map(([v, label]) => <div key={label}><span>{label}</span><strong>{v}</strong></div>)}</div>}
      {stats?.progress && <div className="notice"><span>{stats.progress.phase} · {stats.progress.completed}{stats.progress.total ? ` / ${stats.progress.total}` : ''}</span>{stats.busy && <progress value={stats.progress.completed} max={stats.progress.total || undefined}/>}</div>}
      {actions.length > 0 && <details className="notice"><summary>待确认操作（{actions.length}）</summary>{actions.map(a => <div className="row" key={a.id}><div className="body">{a.description}<div className="muted">{a.created_at}</div></div><button disabled={busy} onClick={() => { setConfirmation(a); setAcknowledged(false); }}>核对操作</button><button onClick={() => void run(async () => { await call('cancel', { id: a.id }); await refresh(); })}>取消</button></div>)}</details>}

      {tab === 0 && <><div className="steps"><div className="step"><b>1. 预览文件</b>检查格式、重复和异常</div><div className="step"><b>2. 确认导入</b>原文存档、本地提取候选</div><div className="step"><b>3. 审核记忆</b>确认后才允许跨会话召回</div></div>
        <div className="file"><label htmlFor="dmb-upload"><strong>选择 DeepSeek 手动导出的 ZIP 或 JSON 文件</strong></label><input id="dmb-upload" type="file" accept=".zip,.json" disabled={busy} onChange={e => { const f = e.target.files?.[0]; if (f) void uploadFile(f); e.target.value = ''; }}/><p className="muted">默认压缩包上限 512 MiB，解压总量上限 1 GiB。仅上传到当前 DSH 主机；本机使用时数据留在本机。真实官方导出样本的适配仍待验证。</p>{upload && <p role="status">{upload}</p>}</div>
        {!imports.length && <div className="empty">还没有导入任务。先在 DeepSeek 网页端手动导出历史数据，再选择本地文件。</div>}
        {imports.map(p => <section className="panel" key={p.id} style={{ marginTop: 16 }}><div className="titlebar"><h2>{p.fileName}</h2><span className="pill">{({ preview: '等待确认', completed: '已导入', importing: '可继续导入', failed: '解析失败', preparing: '预览中断，请重新选择文件' } as any)[p.status]}</span></div><dl><dt>总会话数 / 可解析会话</dt><dd>{p.conversations} / {p.parseable}</dd><dt>消息数</dt><dd>{p.messages}</dd><dt>重复会话 / 已存在会话的新版本</dt><dd>{p.duplicates} / {p.updated}</dd><dt>异常及警告项</dt><dd>{p.anomalies}</dd><dt>已提交会话</dt><dd>{p.cursor}</dd></dl><details><summary>格式说明与异常报告</summary>{p.warnings.map((w: string) => <p key={w} className="muted">{w}</p>)}<code>SHA-256: {p.hash}</code></details>{['preview', 'importing'].includes(p.status) && <button className="primary" disabled={busy} onClick={() => void run(() => propose('import', { id: p.id }, `导入 ${p.fileName}：${p.parseable} 个可解析会话、${p.messages} 条消息，并在本地提取候选记忆`))}>{p.status === 'importing' ? '继续导入' : '核对并导入'}</button>}</section>)}
      </>}

      {tab === 1 && <><div className="bar"><input aria-label="搜索记忆" placeholder="搜索记忆或来源主题" value={query} onChange={e => { setQuery(e.target.value); setOffset(0); }}/><select aria-label="记忆状态" value={status} onChange={e => { setStatus(e.target.value); setOffset(0); }}>{Object.entries(statuses).map(([k, v]) => <option value={k} key={k}>{v}</option>)}</select><select aria-label="记忆分类" value={category} onChange={e => { setCategory(e.target.value); setOffset(0); }}><option value="">全部分类</option>{Object.entries(categoryNames).map(([k, v]) => <option value={k} key={k}>{v}</option>)}</select>{checked.length > 1 && <button onClick={() => setMergeText(items.filter(m => checked.includes(m.id)).map(m => m.content).join('\n'))}>合并所选（{checked.length}）</button>}</div>
        {query && <p className="muted">搜索跨分类返回候选、已确认及未到期条目；结果中的状态以每条标记为准。</p>}
        {!items.length && <div className="empty">当前没有匹配记忆。导入后只提取明确的长期陈述，未命中的内容仍可在历史记录中查找。</div>}
        {items.map(m => <article className="row" key={m.id}><input type="checkbox" aria-label={`选择记忆 ${m.id}`} checked={checked.includes(m.id)} onChange={e => setChecked(e.target.checked ? [...checked, m.id] : checked.filter(id => id !== m.id))}/><div className="body"><div className="stack"><span className={'pill ' + m.status}>{statuses[m.status]}</span><span className="muted">{categoryNames[m.category]} · {m.scope === 'global' ? '全局' : m.scope} · {m.evidence === 'user-stated' ? '用户陈述' : '待验证推断'}</span></div><p className="content">{m.content}</p><span className="time">来源 {m.sources.length} 处 · {m.sources[0]?.originalTime || '原始时间未知'}</span></div><div className="actions"><button onClick={() => { setSelected(m); setRevisions([]); }}>查看证据 / 编辑</button>{m.status === 'candidate' && <button disabled={busy} onClick={() => void review(m, 'confirmed')}>确认记忆</button>}</div></article>)}
        {!query && <div className="bar" style={{ marginTop: 16 }}><button disabled={offset === 0} onClick={() => setOffset(Math.max(0, offset - 50))}>上一页</button><span className="muted">第 {offset / 50 + 1} 页</span><button disabled={items.length < 50} onClick={() => setOffset(offset + 50)}>下一页</button></div>}
      </>}

      {tab === 2 && <><div className="bar"><input className="grow" aria-label="搜索原始对话" placeholder="按消息关键词搜索历史对话" value={query} onChange={e => { setQuery(e.target.value); setOffset(0); }}/></div>{!history.length && <div className="empty">没有匹配对话。原始数据会在确认导入后显示。</div>}{history.map(c => <article className="row" key={c.id}><div className="body"><h3>{c.title}</h3><span className="time">{c.original_time || '原始时间未知'}{c.message_count != null ? ` · ${c.message_count} 条消息` : ''}</span><div><code>{c.source_id}</code></div></div><button onClick={() => void openConversation(c.id)}>查看原文</button></article>)}<div className="bar" style={{ marginTop: 16 }}><button disabled={offset === 0} onClick={() => setOffset(Math.max(0, offset - 50))}>上一页</button><span className="muted">第 {offset / 50 + 1} 页</span><button disabled={history.length < 50} onClick={() => setOffset(offset + 50)}>下一页</button></div></>}

      {tab === 3 && <>{!conflicts.length && <div className="empty">没有待处理冲突。对于同一作用域、同一属性的新旧值，插件会保留两条候选并要求人工选择。</div>}{conflicts.map(c => <section className="panel" key={c.id} style={{ marginBottom: 16 }}><h2>同一属性存在不同值</h2><p className="muted">属性：{c.old.key}；不按时间自动覆盖。请结合来源判断。</p><div className="split">{[['old', c.old, '保留旧版本'], ['new', c.new, '保留新版本']].map(([key, value, label]) => { const m = value as Memory; return <div key={key as string}><p className="content">{m.content}</p><p className="time">{m.sources[0]?.originalTime || '时间未知'}</p><blockquote>{m.sources[0]?.quote}</blockquote><button disabled={busy} onClick={() => void run(() => propose('resolve', { id: c.id, keep: key }, `${label}并将另一条标为已更新`))}>{label as string}</button></div>; })}</div></section>)}</>}

      {tab === 4 && <><section className="panel" style={{ marginBottom: 24 }}><h2>存储位置</h2><p className="small-label">当前记忆库</p><code>{stats?.dataDir}</code><p className="muted">可选择 D 盘或其他数据盘。迁移包含数据库、原始存档、备份、导出文件及未完成的导入和上传。重启 DSH 后仍使用所选位置。</p><label>目标文件夹<input aria-label="目标文件夹" placeholder="D:\DeepSeekMemoryBridge" value={storagePath} onChange={e => setStoragePath(e.target.value)}/></label><div className="stack"><button disabled={busy} onClick={() => void chooseFolder()}>选择文件夹</button><button disabled={busy} onClick={() => void run(() => browse())}>浏览磁盘</button><button className="primary" disabled={busy || !storagePath.trim()} onClick={() => void run(() => propose('storage', { path: storagePath, mode: 'migrate' }, `将当前记忆库从 ${stats?.dataDir} 完整迁移到 ${storagePath}。目标文件夹必须为空。数据库和文件校验成功、切换位置后才会删除旧目录。`))}>迁移当前记忆库</button><button disabled={busy || !storagePath.trim()} onClick={() => void run(() => propose('storage', { path: storagePath, mode: 'open' }, `打开 ${storagePath} 中已有的 Memory Bridge 记忆库。当前目录保留，两个记忆库不会合并。`))}>打开已有记忆库</button></div><p className="muted">读取其他盘中已导入的内容时，请选择同时包含 memory.sqlite 和 archives 的文件夹。DeepSeek 导出的 ZIP 或 JSON 文件请在“导入中心”导入。</p></section><div className="notice">当前提取：本地规则。自动召回：{stats?.settings.autoRecall ? '开启' : '关闭'}。如其他记忆插件也在召回，请留意重复信息。</div><div className="split"><section><h2>召回与本地存储</h2><label><input type="checkbox" checked={autoRecall} onChange={e => setAutoRecall(e.target.checked)}/>自动召回已确认、相关且未过期的用户陈述</label><label>每次召回 Token 上限（保守估算）<input type="number" min="128" max="8000" value={budget} onChange={e => setBudget(Number(e.target.value))}/></label><label>最多召回记忆条数<input type="number" min="1" max="20" value={limit} onChange={e => setLimit(Number(e.target.value))}/></label><label>自动保留备份数<input type="number" min="1" max="100" value={keep} onChange={e => setKeep(Number(e.target.value))}/></label><button className="primary" onClick={() => void run(() => propose('settings', { autoRecall, recallBudgetTokens: budget, recallLimit: limit, backupKeep: keep }, '保存召回与备份设置'))}>保存设置</button><p className="muted">最近导入：{stats?.lastImport || '尚未导入'}<br/>卸载插件保留数据。数据库、原始存档和备份均为明文。</p></section><section><h2>备份、恢复与导出</h2><div className="stack"><button onClick={() => void run(() => propose('backup', {}, '创建包含数据库及原始文件的本地备份'))}>创建备份</button><button onClick={() => void run(() => propose('export', { format: 'json' }, '导出 JSON 记忆列表'))}>导出 JSON</button><button onClick={() => void run(() => propose('export', { format: 'markdown' }, '导出 Markdown 记忆列表'))}>导出 Markdown</button></div>{!backups.length && <div className="empty">暂无备份。导入前后会自动创建备份。</div>}{backups.map(b => <div className="row" key={b.id}><div className="body"><span className="time">{b.createdAt}</span><div className="muted">{backupReasons[b.reason] || b.reason}</div></div><button onClick={() => void run(() => propose('restore', { backupId: b.id }, '恢复备份，替换活动记忆库和原始存档；恢复前会另存当前状态'))}>恢复</button></div>)}</section></div><details className="notice"><summary>隐私、提取和检索范围</summary><p>本插件不会读取 Cookie、DSH 凭据或浏览器账号。原始历史按原样保留，因此可能包含你曾在聊天中输入的敏感内容；长期记忆会拦截常见凭据。当前检索使用 SQLite FTS5 与中俄英关键词，不依赖付费 Embedding 服务。</p><p>本地提取仅生成候选，支持有限的中文、英语和俄语陈述规则；未识别内容仍保存在历史库。可在原始会话详情中选择本地或远程兼容模型进一步提取。远程发送需要单独勾选授权并确认。</p></details></>}
    </div>

    {folderBrowser && <div className="dialog" role="dialog" aria-modal="true" aria-label="选择存储文件夹"><div className="dialog-inner"><div className="titlebar"><h2>选择存储文件夹</h2><button onClick={() => setFolderBrowser(null)}>关闭</button></div><p className="muted">选择磁盘和已有文件夹；也可关闭此窗口，在“目标文件夹”中输入新的专用目录。</p><code>{folderBrowser.path || '可用磁盘'}</code><div className="stack"><button onClick={() => void run(() => browse())}>返回磁盘列表</button>{folderBrowser.parent && <button onClick={() => void run(() => browse(folderBrowser.parent))}>上一级</button>}{folderBrowser.path && <button className="primary" onClick={() => { setStoragePath(folderBrowser.path); setFolderBrowser(null); }}>使用此文件夹</button>}</div>{folderBrowser.directories.map((path: string) => <div className="row" key={path}><button className="link" onClick={() => void run(() => browse(path))}>{path}</button></div>)}{folderBrowser.truncated && <p className="muted">仅显示前 300 个文件夹。其他文件夹可直接输入完整路径。</p>}</div></div>}

    {selected && <div className="dialog" role="dialog" aria-modal="true" aria-label="记忆证据与编辑"><div className="dialog-inner"><div className="titlebar"><h2>记忆证据与编辑</h2><button onClick={() => setSelected(null)}>关闭</button></div><p className="muted">{selected.id} · 修订 {selected.revision}</p><label>记忆内容<textarea value={selected.content} onChange={e => setSelected({ ...selected, content: e.target.value })}/></label><div className="split"><label>分类<select value={selected.category} onChange={e => setSelected({ ...selected, category: e.target.value as any })}>{Object.entries(categoryNames).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></label><label>作用域<input value={selected.scope} onChange={e => setSelected({ ...selected, scope: e.target.value })}/></label></div><div className="stack"><button onClick={() => void run(() => propose('update', { id: selected.id, content: selected.content, category: selected.category, scope: selected.scope, revision: selected.revision }, '保存编辑并重新进入候选审核'))}>保存编辑</button>{selected.status === 'candidate' && <><button onClick={() => void review(selected, 'confirmed')}>确认记忆</button><button onClick={() => void review(selected, 'rejected')}>拒绝候选</button></>}<button className="danger" onClick={() => void run(() => propose('delete', { id: selected.id, revision: selected.revision }, '删除记忆并停止召回，保留历史修订和原文'))}>删除</button><button className="danger" onClick={() => void run(() => propose('purge', { id: selected.id }, '永久移除活动数据库中的这条记忆及修订。原始聊天和备份保留。'))}>永久移除记忆</button></div>{selected.sources.map((s, i) => <div className="source" key={i}><p className="time">用户原始陈述 · {s.originalTime || '时间未知'}</p><blockquote>{s.quote}</blockquote><code>{s.messageId}</code><div><button className="link" onClick={() => { setSelected(null); void openConversation(s.conversationId, s.version); }}>定位原始会话</button></div></div>)}<button className="link" onClick={() => void run(async () => setRevisions(await call('revisions', { id: selected.id })))}>查看修订历史</button>{revisions.map(r => <div className="source" key={r.revision}><p className="time">修订 {r.revision} · {r.time} · {r.reason}</p><p className="content">{r.snapshot.content}</p><button onClick={() => void run(() => propose('rollback', { id: selected.id, targetRevision: r.revision, revision: selected.revision }, `回滚到修订 ${r.revision}，并重新进入审核`))}>回滚至此修订</button></div>)}</div></div>}

    {conversation && <div className="dialog" role="dialog" aria-modal="true" aria-label="原始会话"><div className="dialog-inner"><div className="titlebar"><h2>{conversation.title}</h2><button onClick={() => setConversation(null)}>关闭</button></div><p className="muted">此处的历史内容均为不可信数据，不会自动执行。分页每次 50 条消息。</p><label>会话版本<select value={conversation.version} onChange={e => void openConversation(conversation.id, e.target.value)}>{conversation.versions.map((v: any) => <option key={v.content_hash} value={v.content_hash}>{v.content_hash.slice(0, 16)} · {v.adapter}</option>)}</select></label>{conversation.messages.map((m: any) => <article className="source" key={m.id}><div className="stack"><span className="pill">{roleNames[m.role] || m.role}</span><span className="time">{m.original_time || '时间未知'}</span></div><p className="content">{m.text}</p><details><summary>消息 ID 与原始字段</summary><pre>{m.raw_json}</pre></details></article>)}<div className="bar"><button onClick={() => void openConversation(conversation.id, conversation.version, Math.max(0, (conversation.messages[0]?.position ?? 0) - 50))} disabled={(conversation.messages[0]?.position ?? 0) === 0}>上一页消息</button><button onClick={() => void openConversation(conversation.id, conversation.version, (conversation.messages.at(-1)?.position ?? 0) + 1)} disabled={conversation.messages.length < 50}>下一页消息</button><button onClick={() => void downloadRaw()}>下载会话原始字段</button></div><details><summary>可选模型提取</summary><p className="muted">将该会话中不含常见凭据的用户消息发送给你选择的模型，AI 回复不会作为用户事实。所有结果仍需审核。</p><label>兼容 API 基地址<input value={endpoint} onChange={e => { setEndpoint(e.target.value); setRemoteConsent(false); }}/></label><label>模型名称<input value={model} onChange={e => setModel(e.target.value)}/></label><label>API Key 环境变量名称（不填入密钥本身）<input value={keyEnv} onChange={e => setKeyEnv(e.target.value)}/></label><label><input type="checkbox" checked={remoteConsent} onChange={e => setRemoteConsent(e.target.checked)}/>若该地址是远程服务，我授权本次发送该会话的用户消息</label><button onClick={() => void run(() => propose('model-extract', { id: conversation.id, endpoint, model, keyEnv, authorizeRemote: remoteConsent }, `使用 ${model} 从此会话提取记忆；目标地址 ${endpoint}，远程发送授权：${remoteConsent ? '是' : '否'}`))}>核对模型提取请求</button></details></div></div>}

    {mergeText && <div className="dialog" role="dialog" aria-modal="true" aria-label="合并记忆"><div className="dialog-inner"><h2>合并相关记忆</h2><p className="muted">保留每条来源，原记忆标为已更新；合并结果需重新审核。</p><textarea aria-label="合并后的记忆内容" value={mergeText} onChange={e => setMergeText(e.target.value)}/><div className="stack"><button onClick={() => void run(async () => { await propose('merge', { ids: checked, content: mergeText }, '合并所选记忆并保留全部来源'); setMergeText(''); })}>核对合并</button><button onClick={() => setMergeText('')}>取消</button></div></div></div>}

    {confirmation && <div className="dialog" role="dialog" aria-modal="true" aria-label="确认操作"><div className="dialog-inner"><h2>确认操作</h2>{error && <div className="notice error" role="alert">{error}</div>}<p>{confirmation.description}</p><details open><summary>完整操作参数</summary><pre>{JSON.stringify(confirmation.payload, null, 2)}</pre></details><label><input type="checkbox" checked={acknowledged} onChange={e => setAcknowledged(e.target.checked)}/>我已核对上述文件、记忆和操作范围，确认执行</label><div className="stack"><button className="primary" disabled={!acknowledged || busy} onClick={() => void run(async () => { const result = await call('confirm', { id: confirmation.id, nonce: confirmation.nonce }); setConfirmation(null); setSelected(null); setNotice(result?.dataDir ? `当前记忆库：${result.dataDir}。${result.warning || (result.sourceRemoved ? '旧数据目录已删除。' : '原记忆库目录已保留。')}` : typeof result?.path === 'string' ? `操作完成，文件位置：${result.path}` : '操作完成。'); setChecked([]); await refresh(); })}>{busy ? '处理中…' : '确认执行'}</button><button disabled={busy} onClick={() => setConfirmation(null)}>返回核对</button></div></div></div>}
  </div>;
}

export const inject = ['slots', 'connection'];
export function apply(ctx: Context): void {
  // Use the actual 0.2.2 settings slot and carrier-neutral Connection RPC, including desktop IPC.
  const connection = ctx.get('connection') as unknown as ConnectionHandle;
  const call: Caller = async (endpoint, payload = {}) => {
    const result = await connection.rpc.call('/api', 'deepseek-memory-bridge', { endpoint, input: payload });
    if (!result.ok) throw new Error(result.error.message); return result.value;
  };
  ctx.slots.inject('settings.section', () => ctx.slots.register({ name: 'settings.section', id: 'deepseek-memory-bridge', order: 46, label: () => 'DeepSeek 记忆桥', inject: () => ({ call }) }, BridgeManager));
}
